/// <summary>
/// N.Freidenberger 25.09.2024
/// </summary>
/// <returns>int</returns>
public int active()
{
    int ret;

    ret = next active();

    AVACustInvoiceLineAdjust locCustInvoiceLineAdj;
    FormControl     locFC_AVABonusAlliance;
    FormControl     locFC_AVABonusCustAccount;
    boolean         locAllowEdit_AVABonusAlliance;


    locCustInvoiceLineAdj = element.dataSource(tableStr(AVACustInvoiceLineAdjust)).cursor();

    if(locCustInvoiceLineAdj.AVABonusAllocationBase == AVABonusAllocationBase::Customer)
    {
        locAllowEdit_AVABonusAlliance = false;
    }
    else if(locCustInvoiceLineAdj.AVABonusAllocationBase == AVABonusAllocationBase::Alliance)
    {
        locAllowEdit_AVABonusAlliance = true;
    }
    locFC_AVABonusAlliance     = element.design().controlName(formControlStr(CustFreeInvoice, AVACustInvoiceLineAdjust_AVABonusAlliance));
    locFC_AVABonusAlliance.allowEdit(locAllowEdit_AVABonusAlliance);


    locFC_AVABonusCustAccount     = element.design().controlName(formControlStr(CustFreeInvoice, AVACustInvoiceLineAdjust_AVABonusCustAccount));
    locFC_AVABonusCustAccount.allowEdit(!locAllowEdit_AVABonusAlliance);


    return ret;
}
